{
  "API_calls": [],
  "collected_information": {
    "programming_language_versions": "Python >=3.10 and <3.13",
    "dependency_installation": {
      "basic": "pip install crewai",
      "with_tools": "pip install 'crewai[tools]'",
      "handling_missing_dependencies": [
        "pip install 'crewai[embeddings]'",
        "pip install 'crewai[tools]'"
      ],
      "rust_compiler_required": true,
      "windows_build_tools": "Visual C++ Build Tools",
      "upgrade_pip": "pip install --upgrade pip",
      "prebuilt_wheel_fallback": "pip install tiktoken --prefer-binary"
    },
    "dependency_management_tool": {
      "tool": "UV",
      "commands": {
        "lock_dependencies": "uv lock",
        "sync_dependencies": "uv sync",
        "create_virtualenv": "uv venv"
      }
    },
    "environment_variables": {
      "file": ".env",
      "required_keys": [
        "OPENAI_API_KEY",
        "SERPER_API_KEY",
        "OTEL_SDK_DISABLED (optional to disable telemetry)"
      ]
    },
    "project_initialization": {
      "command": "crewai create crew <project_name>",
      "structure": [
        ".env",
        "pyproject.toml",
        "src/<project_name>/"
      ]
    },
    "running_tests": {
      "all_tests": "uv run pytest .",
      "specific_test_file": "uv run pytest path/to/test_file.py",
      "static_type_checking": "uvx mypy src"
    },
    "additional_commands": {
      "install_pre_commit_hooks": "pre-commit install",
      "build_package": "uv build",
      "local_install": "pip install dist/*.tar.gz"
    },
    "running_project": [
      "crewai run",
      "python src/my_project/main.py",
      "fix_poetry_issues: crewai update"
    ],
    "system_requirements": [
      "Python 3.10 to 3.12",
      "Rust compiler for certain dependencies",
      "Visual C++ Build Tools on Windows"
    ]
  },
  "terminate": true
}
